begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000000951','io-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000000952','io-readonly@example.test',now()),
 ('f0000000-0000-4000-8000-000000000953','io-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000951","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Items overview test','items-overview-test',gen_random_uuid())::text,true);
select set_config('test.s1',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Anna Andersson','anna@io.test','')::text,true);
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic terms','Only a test','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.s1')::uuid,current_setting('test.agreement')::uuid,'Signed paper');
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy') || '{"vatModeConsignmentPrivate":"consignment_margin","vatModeStoreOwned":"store_full"}'::jsonb);
select set_config('test.bag',receive_bag_with_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.s1')::uuid,'',current_setting('test.agreement')::uuid)::text,true);
select set_config('test.d1',gen_random_uuid()::text,true);
select save_inspection_draft(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.d1')::uuid,0,'Blue wool jacket','Jackets','Good');
select set_config('test.i1',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.i1')::uuid,'inspection_draft',current_setting('test.d1')::uuid,1,20000);
select set_config('test.d2',gen_random_uuid()::text,true);
select save_inspection_draft(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.d2')::uuid,0,'Red coat','Coats','Good');
select set_config('test.i2',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.i2')::uuid,'inspection_draft',current_setting('test.d2')::uuid,1,30000);
select set_config('test.p',gen_random_uuid()::text,true);
select register_purchase(current_setting('test.tenant')::uuid,current_setting('test.p')::uuid,'Vintage lamp',15000,'Auction receipt 7',false);
select set_config('test.i3',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.i3')::uuid,'purchase',current_setting('test.p')::uuid,null,25000);
select record_sale(current_setting('test.tenant')::uuid,gen_random_uuid(),'manual','K-1','2026-09-10T10:00:00Z','SEK',jsonb_build_array(jsonb_build_object('itemId',current_setting('test.i1'),'priceOre',20000)));


select is((items_search_page(current_setting('test.tenant')::uuid,'{}','price','asc',1,0)->'items'->0->>'currentPriceOre')::bigint,20000::bigint,'price sorting happens before paging');
select is((items_search_page(current_setting('test.tenant')::uuid,'{}','price','asc',1,1)->'items'->0->>'currentPriceOre')::bigint,25000::bigint,'second price page');
select is((items_search_page(current_setting('test.tenant')::uuid,'{}','price','desc',1,0)->'items'->0->>'currentPriceOre')::bigint,30000::bigint,'descending numeric price');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"ownership":"consignment","category":"Coats","seller":"Anna","minPrice":"250","maxPrice":"350"}','title','asc',25,0)->>'total')::int,1,'advanced filters intersect before counts');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"q":"%"}','accepted','desc',25,0)->>'total')::int,0,'wildcards remain literal');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"photo":"yes"}','accepted','desc',25,0)->>'total')::int,0,'no fabricated photos');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"photo":"no"}','accepted','desc',25,0)->>'total')::int,3,'no-photo filter');
select is((items_search_page(current_setting('test.tenant')::uuid,jsonb_build_object('acceptedFrom',to_char(now() at time zone 'Europe/Stockholm','YYYY-MM-DD'),'acceptedTo',to_char(now() at time zone 'Europe/Stockholm','YYYY-MM-DD')),'accepted','desc',25,0)->>'total')::int,3,'date bounds include the whole local day');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"acceptedTo":"2000-01-01"}','accepted','desc',25,0)->>'total')::int,0,'date filtering');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"origin":"purchase","stage":"sold"}','accepted','desc',25,0)->>'total')::int,0,'origin and stage intersect');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{"minPrice":"100","maxPrice":"1"}','accepted','desc',25,0)$$,'INVALID_INPUT','reversed price range rejected');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{"ownership":"unknown"}','accepted','desc',25,0)$$,'INVALID_INPUT','unknown ownership rejected');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{}','injection','desc',25,0)$$,'INVALID_INPUT','sort whitelist');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{"unexpected":"x"}','accepted','desc',25,0)$$,'INVALID_INPUT','unknown filters rejected');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{}','accepted','desc',25,-1)$$,'INVALID_INPUT','negative page refused');
select set_config('test.photo',gen_random_uuid()::text,true);
insert into storage.objects(bucket_id,name) values('item-photos',current_setting('test.tenant')||'/'||current_setting('test.i2')||'/'||current_setting('test.photo')||'.jpg');
select change_item_photo(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.i2')::uuid,0,'add',current_setting('test.photo')::uuid);
select is(items_search_page(current_setting('test.tenant')::uuid,'{"photo":"yes"}','title','asc',25,0)->'items'->0->>'defaultPhotoId',current_setting('test.photo'),'photo filter returns current default');
select is((items_search_page(current_setting('test.tenant')::uuid,'{"photo":"no"}','title','asc',25,0)->>'total')::int,2,'photo presence changes totals');
select change_item_photo(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.i2')::uuid,1,'remove',current_setting('test.photo')::uuid);
select is((items_search_page(current_setting('test.tenant')::uuid,'{"photo":"yes"}','title','asc',25,0)->>'total')::int,0,'removed photos are absent');
select is(items_search_page(current_setting('test.tenant')::uuid,'{"category":"Coats"}','title','asc',25,0)->'items'->0->>'sellerName','Anna Andersson','seller facts belong to matching item');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{"acceptedFrom":"2026-02-30"}','accepted','desc',25,0)$$,'INVALID_INPUT','invalid calendar date rejected');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{"minPrice":"0.001"}','accepted','desc',25,0)$$,'INVALID_INPUT','sub-ore prices refused');
select set_config('test.other',create_tenant('Other inventory','other-inventory',gen_random_uuid())::text,true);
select is((items_search_page(current_setting('test.other')::uuid,'{"seller":"Anna"}','seller','asc',25,0)->>'total')::int,0,'membership in both stores never mixes rows or counts');
reset role;
insert into tenant_members(tenant_id,user_id,role) values (current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000000952','readonly');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000952","role":"authenticated"}';
select lives_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{}','seller','asc',25,0)$$,'readonly staff can search');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000953","role":"authenticated"}';
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{}','seller','asc',25,0)$$,'42501',null,'outsider cannot read rows or counts');
reset role;
select ok(not has_function_privilege('anon','public.items_search_page(uuid,jsonb,text,text,integer,integer)','execute'),'anonymous denied');
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),'f0000000-0000-4000-8000-000000000952','totp','verified',now(),now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000952","role":"authenticated","aal":"aal1"}';
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{}','accepted','desc',25,0)$$,'42501',null,'MFA still required');
select * from finish();
rollback;
